/**
 * 分支 D：Windows 系统语音（SAPI 5，经 PowerShell 调用）。
 *
 * ## 为什么走 PowerShell 而不是外部 CLI
 *
 * `System.Speech.Synthesis.SpeechSynthesizer` 随 .NET Framework 装在 Windows
 * 上；这里不装包、不下载语音、不把文本拼进命令行。启动 PowerShell 时用
 * `-EncodedCommand` 传 UTF-16LE 脚本，中文与引号都不会经过控制台代码页。
 *
 * ## 文本为什么走临时文件
 *
 * 回复里常有引号、连字符、换行。`--text "..."` 这类参数在 PowerShell 里
 * 会被二次解释；写进 `.txt` 后由 `.NET` 直接 `ReadAllText`，原文一个字节不改。
 * 用完立刻删，避免缓存目录里堆一份可读的对话记录。
 *
 * ## 语速、音量与音色
 *
 * `Rate` 是 −10..10 的档位（相对增量 × 10），`Volume` 是 0..100；
 * `SelectVoice()` 只接受系统已安装的**全名**。Edge 的音色 id 在这一支
 * 没有意义，所以 `sapiVoice` 留空时用系统默认，不猜名字。
 */
import { unlink, writeFile } from 'node:fs/promises';
import { encodedPowerShell, psLiteral } from '../exec.js';

/** SAPI 语速档位下限 / 上限。 */
export const SAPI_RATE_MIN = -10;
export const SAPI_RATE_MAX = 10;

/**
 * 相对语速增量 → SAPI 档位。
 * @param rate 相对增量（0.1 = 快一成）。
 */
export function sapiRateOf(rate) {
    const scaled = Math.round(rate * 10);
    return Math.min(SAPI_RATE_MAX, Math.max(SAPI_RATE_MIN, scaled));
}

/**
 * 音量档 → SAPI 整数音量。
 * @param volume 音量档。
 */
export function sapiVolumeOf(volume) {
    return volume === 'low' ? 60 : 100;
}

/**
 * 构造一段只使用字面量的 PowerShell 脚本。
 *
 * 路径、文本、音色名分别做单引号转义；`ErrorActionPreference = Stop`
 * 让 `SelectVoice()` 找不到音色时以非零退出，供服务层报 `voice-unknown`。
 * @param options 脚本参数。
 */
export function sapiScript(options) {
    return [
        '$ErrorActionPreference = \'Stop\'',
        `Add-Type -AssemblyName System.Speech`,
        '$synth = New-Object System.Speech.Synthesis.SpeechSynthesizer',
        `try {`,
        options.voice === '' ? '' : `    $synth.SelectVoice(${psLiteral(options.voice)})`,
        `    $synth.Rate = ${String(options.rate)}`,
        `    $synth.Volume = ${String(options.volume)}`,
        `    $text = [System.IO.File]::ReadAllText(${psLiteral(options.textPath)})`,
        `    $synth.SetOutputToWaveFile(${psLiteral(options.outPath)})`,
        `    $synth.Speak($text)`,
        `    $synth.SetOutputToNull()`,
        `} finally {`,
        `    $synth.Dispose()`,
        `}`,
    ].filter(line => line !== '').join('\n');
}

/** Windows 系统语音分支。 */
export class WindowsSapiEngine {
    name = 'windows-sapi';
    options;
    constructor(options) {
        this.options = options;
    }
    /** 系统音色名（不是 Edge 音色 id）。 */
    get voice() {
        return this.options.voice;
    }
    get present() {
        return this.options.platform === 'win32' && this.options.powershell !== undefined;
    }
    get configured() {
        return true; // 系统默认音色即可工作，不要求用户配置。
    }
    get detail() {
        if (this.options.platform !== 'win32')
            return '不是 Windows';
        if (this.options.powershell === undefined)
            return '找不到 powershell.exe';
        return this.options.voice === ''
            ? '就绪（系统默认音色）'
            : '就绪（系统音色 ' + this.options.voice + '）';
    }
    async synth(request) {
        const base = { ext: 'wav', rateApplied: true, voice: this.options.voice };
        if (!this.present)
            return { ok: false, reason: 'no-engine', ...base };
        const textPath = request.outPath + '.txt';
        try {
            await writeFile(textPath, request.text, 'utf8');
        }
        catch {
            return { ok: false, reason: 'spawn', ...base };
        }
        const result = await this.options.exec(this.options.powershell, [
            '-NoProfile',
            '-NonInteractive',
            '-EncodedCommand',
            encodedPowerShell(sapiScript({
                textPath,
                outPath: request.outPath,
                voice: this.options.voice,
                rate: sapiRateOf(request.rate),
                volume: sapiVolumeOf(request.volume),
            })),
        ], { timeoutMs: this.options.timeoutMs });
        // 原文含完整回复：无论合成成败都要删，不让对话留在 cache/tts 里。
        try {
            await unlink(textPath);
        }
        catch {
            // 删不掉不影响音频结果；下一次淘汰也不会把它当缓存条目。
        }
        if (result.timedOut)
            return { ok: false, reason: 'timeout', ...base };
        if (!result.ok) {
            if (/voice not installed|not a valid voice|SelectVoice/i.test(result.stderr)) {
                return { ok: false, reason: 'voice-unknown', ...base };
            }
            return { ok: false, reason: 'spawn', ...base };
        }
        return { ok: true, reason: 'ok', ...base };
    }
}
